mapper.select:
SELECT SQL_CALC_FOUND_ROWS ROW_NUMBER() OVER ( ORDER BY CASE WHEN user_type = 'SUPER_ADMIN' THEN 0 ELSE 1 END, create_ymd DESC ) AS row_num, admin_id, company, username, name, last_accessed_at, user_type, user_status_type, create_ymd FROM pet_admin WHERE del_fl = 0
AND (name LIKE CONCAT('%', #{searchKeyword}, '%'))
LIMIT #{pageNo}, #{pageSize};

SELECT admin_id, username, password, user_status_type
FROM pet_admin
WHERE username = #{username}
  and del_fl = 0;

mapper.update:
UPDATE pet_admin
SET
user_status_type = #{userStatusType},
update_ymd = CURRENT_TIMESTAMP,
update_id = #{createOrUpdateId}

  , password = #{password}

WHERE admin_id = #{adminId}

UPDATE pet_admin
SET del_fl = 1
WHERE admin_id = #{adminId}

UPDATE pet_admin
SET last_accessed_at = CURRENT_TIMESTAMP
WHERE admin_id = #{adminId}

mapper.select:
SELECT SQL_CALC_FOUND_ROWS pr.place_id, pp.name AS placeName, pr.review_id, CASE WHEN pi.pet_type_cd = 'CAT' THEN '고양이' ELSE '강아지' END AS pet_type_nm, fn_codeNm(pi.pet_type_cd, pi.pet_kind_cd, true) AS pet_kind_nm, CONCAT(TIMESTAMPDIFF(MONTH, birth_dt, CURRENT_DATE), '개월') AS birth_dt, CASE WHEN pi.sex = 'FEMALE' THEN '암컷' ELSE '수컷' END AS sex_nm, pr.mb_id, pr.pet_id, pr.point, (SELECT COUNT(*) FROM pet_review_like_mapping WHERE review_id = pr.review_id) AS like_total_cnt, pr.tag_name, pr.visit_reason, pr.visit_content, IFNULL((SELECT bf_fileurl FROM pet_review_file_mapping prfm INNER JOIN g5_board_file gbf ON gbf.bo_table = 'pet_review' AND prfm.rfm_id = gbf.wr_id WHERE prfm.review_id = pr.review_id ORDER BY prfm.create_ymd LIMIT 1), NULL) AS file_url, (SELECT COUNT(*) FROM pet_review_file_mapping WHERE review_id = pr.review_id AND mb_id = pr.mb_id) AS review_file_count, pr.point FROM pet_review pr INNER JOIN pet_info pi ON pr.mb_id = pi.mb_id AND pr.pet_id = pi.pet_id AND pr.del_fl = pi.del_fl INNER JOIN pet_place pp ON pr.place_id = pp.id AND pr.del_fl = pp.del_fl WHERE pi.del_fl = 0
AND ((pr.visit_reason LIKE CONCAT('%', #{searchKeyword}, '%')) OR (pr.visit_content LIKE CONCAT('%', #{searchKeyword}, '%')))
ORDER BY pr.create_ymd DESC LIMIT #{pageNo}, #{pageSize};

SELECT SQL_CALC_FOUND_ROWS pcb.cm_board_id, pcb.mb_id, pcb.subject, pcb.contents, (SELECT COUNT(*) FROM pet_cm_like_mapping WHERE cm_board_id = pcb.cm_board_id) AS like_cnt, JSON_ARRAYAGG( JSON_OBJECT( 'cmFmapId', pcfm.cm_fmap_id, 'imageUrl', g5bf.bf_fileurl, 'fileName', g5bf.bf_source ) ) AS image_list FROM pet_cm_board pcb LEFT JOIN pet_cm_file_mapping pcfm ON pcb.cm_board_id = pcfm.cm_board_id LEFT JOIN g5_board_file g5bf ON pcfm.cm_fmap_id = g5bf.wr_id AND g5bf.bo_table = 'pet_cm_board' WHERE pcb.del_fl = 0
AND ((pcb.mb_id LIKE CONCAT('%', #{searchKeyword}, '%')) OR (pcb.subject LIKE CONCAT('%', #{searchKeyword}, '%')) OR (pcb.contents LIKE CONCAT('%', #{searchKeyword}, '%')))
GROUP BY pcfm.cm_board_id ORDER BY pcb.create_ymd DESC LIMIT #{pageNo}, #{pageSize};

SELECT SQL_CALC_FOUND_ROWS pp.id AS place_id, pp.name AS place_name, pp.category_cd AS category_cd, pp.category_group_name, pp.category_name AS category_name, pp.status, pp.tel AS phone, pp.full_address AS address_name, pp.road_address AS road_address_name, pp.x_position AS x, pp.y_position AS y, pp.place_url, pp.description, (SELECT bf_fileurl FROM g5_board_file gbf INNER JOIN pet_place_file_mapping ppfm ON gbf.bo_table = 'pet_place' AND gbf.wr_id = ppfm.pfm_id WHERE ppfm.place_id = pp.id LIMIT 1) AS image_url, pp.opening_hours, IFNULL((SELECT CAST(AVG(point) AS signed integer) FROM pet_review WHERE place_id = pp.id), 0) AS point FROM pet_place pp WHERE pp.del_fl = 0
AND pp.category_cd = #{categoryCd}
AND ((pp.name LIKE CONCAT('%', #{searchKeyword}, '%')) OR (pp.road_address LIKE CONCAT('%', #{searchKeyword}, '%')))
ORDER BY pp.sido_code LIMIT #{pageNo}, #{pageSize};

mapper.insert:
INSERT INTO pet_place_file_mapping (
    place_id,
    create_id
) VALUES (
             #{placeId},
             #{createOrUpdateId}
         );
